pub fn from_buf_and_len(buf: [T; N], len: usize) -> Self {
        assert!(len <= N);
        // SAFETY: all the members in 0..len are initialized
        let mut vec: SmallVec<T, N> = Self {
            len: TaggedLen::new(len, on_heap: false, Self::is_zst()),
            raw: RawSmallVec::new_inline(MaybeUninit::new(val: buf)),
            _marker: PhantomData,
        };
        // Deallocate the remaining elements so no memory is leaked.
        unsafe {
            // SAFETY: both the input and output pointers are in range of the stack allocation
            let remainder_ptr: *mut T = vec.raw.as_mut_ptr_inline().add(count: len);
            let remainder_len: usize = N - len;

            // SAFETY: the values are initialized, so dropping them here is fine.
            core::ptr::drop_in_place(to_drop: core::ptr::slice_from_raw_parts_mut(
                data: remainder_ptr,
                remainder_len,
            ));
        }

        vec
    }

detail_info.documentation:
Executes the destructor (if any) of the pointed-to value.

This is semantically equivalent to calling [`ptr::read`] and discarding
the result, but has the following advantages:

* It is *required* to use `drop_in_place` to drop unsized types like
  trait objects, because they can't be read out onto the stack and
  dropped normally.

* It is friendlier to the optimizer to do this over [`ptr::read`] when
  dropping manually allocated memory (e.g., in the implementations of
  `Box`/`Rc`/`Vec`), as the compiler doesn't need to prove that it's
  sound to elide the copy.

* It can be used to drop [pinned] data when `T` is not `repr(packed)`
  (pinned data must not be moved before it is dropped).

Unaligned values cannot be dropped in place, they must be copied to an aligned
location first using [`ptr::read_unaligned`]. For packed structs, this move is
done automatically by the compiler. This means the fields of packed structs
are not dropped in-place.

